import { normalizeRows } from './data-model.js';
import { buildModelFromWorkbook, loadWorkbook } from './xlsx-loader.js';
import { DAYS, generateTimetable, regenerateClassTimetable } from './scheduler.js';
import { buildExportDocument, downloadPdf, downloadTeacherPdf } from './export.js';
import { renderShell, renderSetup, renderGenerated, renderTeacherTimetable, renderLabTimetable, renderConflictPanel, renderManualPanel } from './ui.js';

const state = { model: null, result: null, selectedClass: '', selectedTeacher: '', template: 'class', view: 'class', manualMode: false, mode: 'setup' };
const content = () => document.querySelector('#content');
const toast = message => { const region = document.querySelector('#toast-region'); const item = document.createElement('div'); item.className = 'toast'; item.textContent = message; region.append(item); setTimeout(() => item.remove(), 3200); };
const setModel = model => { state.model = model; state.result = null; state.mode = 'setup'; state.selectedClass = model.classes[0] || ''; model.metadata = model.metadata || {}; localStorage.setItem('rpsit-model', JSON.stringify(model)); document.querySelector('#class-selector').innerHTML = model.classes.map(c => `<option value="${c}">${c}</option>`).join(''); document.querySelector('#class-selector').disabled = false; document.querySelector('#generate-button').disabled = false; document.querySelector('#class-selector').value = state.selectedClass; content().innerHTML = renderSetup({ ...model, activeClass: state.selectedClass, filename: state.filename }); bindSetup(); toast(`Loaded ${model.classes.length} class${model.classes.length === 1 ? '' : 'es'}. Select a class above to configure and generate it.`); };
const rerenderSetup = () => { content().innerHTML = renderSetup({ ...state.model, activeClass: state.selectedClass, filename: state.filename }); bindSetup(); };
const toggleClassRole = (person, field, className) => { const values = new Set(person[field] || []); if (values.has(className)) values.delete(className); else values.add(className); person[field] = [...values]; };
const bindSetup = () => { document.querySelector('#file-input')?.addEventListener('change', handleFile); document.querySelector('#validate-button')?.addEventListener('click', generate); document.querySelectorAll('.template-option:not(:disabled)').forEach(button => button.addEventListener('click', () => { state.template = button.dataset.template; document.querySelectorAll('.template-option').forEach(x => x.classList.toggle('selected', x === button)); if (state.result) openView(state.template); })); document.querySelectorAll('[data-staff-hod]').forEach(button => button.addEventListener('click', () => { const name = button.dataset.staffHod; const person = state.model.teachers[name] || Object.values(state.model.teachers).find(item => item.name === name); if (!person) return; delete person.isHod; toggleClassRole(person, 'hodFor', state.selectedClass); state.model.staff = Object.values(state.model.teachers); localStorage.setItem('rpsit-model', JSON.stringify(state.model)); const active = person.hodFor.includes(state.selectedClass); rerenderSetup(); toast(`${name} ${active ? 'is now' : 'is no longer'} HOD for ${state.selectedClass}.`); })); document.querySelectorAll('[data-staff-cc]').forEach(button => button.addEventListener('click', () => { const name = button.dataset.staffCc; const person = state.model.teachers[name] || Object.values(state.model.teachers).find(item => item.name === name); if (!person) return; toggleClassRole(person, 'ccFor', state.selectedClass); state.model.staff = Object.values(state.model.teachers); localStorage.setItem('rpsit-model', JSON.stringify(state.model)); const active = person.ccFor.includes(state.selectedClass); rerenderSetup(); toast(`${name} ${active ? 'is now' : 'is no longer'} CC for ${state.selectedClass}.`); })); document.querySelectorAll('[data-extracurricular]').forEach(input => input.addEventListener('change', () => { const subject = state.model.subjects.find(item => item.id === input.dataset.extracurricular); if (!subject) return; subject.isExtracurricular = input.checked; localStorage.setItem('rpsit-model', JSON.stringify(state.model)); rerenderSetup(); toast(`${subject.name} set as ${input.checked ? 'extracurricular' : 'theory'}.`); })) };
async function handleFile(event) { const file = event.target.files[0]; if (!file) return; const error = document.querySelector('#upload-error'); try { const model = await buildModelFromWorkbook(file); state.filename = file.name; setModel(model); } catch (err) { error.hidden = false; error.textContent = err.validation?.missing?.length ? `Missing columns: ${err.validation.missing.join(', ')}` : err.message; toast('Upload needs attention.'); } }
function selectedSchedule() { return state.result?.schedules?.[state.selectedClass] || Object.values(state.result?.schedules || {})[0]; }
function renderCurrentView() { if (!state.result) { state.mode = 'setup'; content().innerHTML = renderSetup(state.model ? { ...state.model, activeClass: state.selectedClass, filename: state.filename } : null); bindSetup(); return; } state.mode = 'generated'; if (state.view === 'teacher') { content().innerHTML = renderTeacherTimetable(state.result, state.model, state.selectedTeacher); bindTeacherView(); } else if (state.view === 'lab') content().innerHTML = renderLabTimetable(state.result, state.model, state.selectedClass); else content().innerHTML = renderGenerated(selectedSchedule(), state.model, state.result.diagnostics, state.result.schedules); if (state.view === 'class') bindGenerated(); }
function openView(view) { if (!state.model) { toast('Upload a workbook first.'); return; } if (!state.result) state.result = generateTimetable(state.model); if (view === 'teacher' && !state.selectedTeacher) state.selectedTeacher = Object.values(state.model.teachers || {})[0]?.name || ''; state.view = view; state.template = view === 'teacher' ? 'teacher' : 'class'; const templateSelector = document.querySelector('#template-selector'); if (templateSelector) templateSelector.value = state.template; document.querySelectorAll('.rail-item').forEach(item => item.classList.toggle('active', item.dataset.view === view)); document.querySelector('h1').textContent = view === 'teacher' ? 'Staff Timetable' : view === 'lab' ? 'Lab Timetable' : 'Class Timetable'; renderCurrentView(); }
function generateAll() { if (!state.model) return; state.model.settings = { ...(state.model.settings || {}), scheduleSeed: Date.now() }; state.result = generateTimetable(state.model); state.view = state.template === 'teacher' ? 'teacher' : 'class'; if (state.view === 'teacher' && !state.selectedTeacher) state.selectedTeacher = Object.values(state.model.teachers || {})[0]?.name || ''; renderCurrentView(); }
function regenerateSelected() { if (!state.model || !state.result || !state.selectedClass) return generateAll(); state.model.settings = { ...(state.model.settings || {}), scheduleSeed: Date.now() }; const previous = state.result; const next = regenerateClassTimetable(state.model, previous, state.selectedClass); const selectedErrors = next.diagnostics.filter(item => item.severity === 'error' && (item.className === state.selectedClass || !item.className)); if (selectedErrors.length === 0 || fixedLabScore(next.schedules[state.selectedClass]) > fixedLabScore(previous.schedules[state.selectedClass])) state.result = { ...next, schedules: { ...previous.schedules, [state.selectedClass]: next.schedules[state.selectedClass] } }; else state.result = previous; state.view = 'class'; renderCurrentView(); }
function regenerateSelectedBest() { if (!state.model || !state.result || !state.selectedClass) return generateAll(); state.model.settings = { ...(state.model.settings || {}), scheduleSeed: Date.now() }; const previous = state.result; const next = regenerateClassTimetable(state.model, previous, state.selectedClass); const selectedErrors = next.diagnostics.filter(item => item.severity === 'error' && (item.className === state.selectedClass || !item.className)); const previousSchedule = previous.schedules[state.selectedClass]; const nextSchedule = next.schedules[state.selectedClass]; const countFilled = schedule => DAYS.reduce((total, day) => total + schedule[day].filter(Boolean).length, 0); const previousFilled = countFilled(previousSchedule); const nextFilled = countFilled(nextSchedule); const previousErrors = previous.diagnostics.filter(item => item.severity === 'error' && (item.className === state.selectedClass || !item.className)).length; const previousFixed = fixedLabScore(previousSchedule); const nextFixed = fixedLabScore(nextSchedule); if (nextFixed > previousFixed || (nextFixed === previousFixed && (nextFilled >= previousFilled || selectedErrors.length < previousErrors))) state.result = { ...next, schedules: { ...previous.schedules, [state.selectedClass]: nextSchedule } }; else state.result = previous; state.view = 'class'; renderCurrentView(); }
function generate() { return state.result ? regenerateSelectedBest() : generateAll(); }
const satisfiesFixedLab = (schedule, lab, subject) => {
  const day = lab.day || subject?.labDay || '';
  const rawStart = lab.startPeriod !== null && lab.startPeriod !== undefined && lab.startPeriod !== '' ? lab.startPeriod : (subject?.labStart ?? null);
  const length = Number(lab.length || lab.labPeriods || subject?.labPeriods || 1);
  const cells = (day ? (schedule[day] || []) : DAYS.flatMap(d => schedule[d] || [])).filter(cell => cell?.subjectId === lab.subjectId);
  if (!cells.length || cells.length < length) return false;
  if (day && DAYS.some(d => d !== day && (schedule[d] || []).some(cell => cell?.subjectId === lab.subjectId))) return false;
  const start = Math.min(...cells.map(cell => cell.period));
  if (rawStart != null && rawStart !== '' && start !== Number(rawStart) - 1) return false;
  for (let offset = 0; offset < length; offset++) if (!cells.some(cell => cell.period === start + offset)) return false;
  return true;
};
const fixedLabScore = schedule => {
  if (!state.model) return 0;
  return (state.model.labs || []).filter(lab => {
    const subject = state.model.subjects.find(item => item.id === lab.subjectId);
    return subject && subject.className === state.selectedClass;
  }).filter(lab => satisfiesFixedLab(schedule, lab, state.model.subjects.find(item => item.id === lab.subjectId))).length;
};
function saveDocumentDetails() { if (!state.model) return; state.model.metadata = { documentId: document.querySelector('#document-id')?.value || '', documentName: document.querySelector('#document-name')?.value || 'Time Table', programme: document.querySelector('#programme')?.value || '', regulation: document.querySelector('#regulation')?.value || '', academicYear: document.querySelector('#academic-year')?.value || '', oddEven: document.querySelector('#odd-even')?.value || '', effectiveDate: document.querySelector('#effective-date')?.value || '', classAdvisor: document.querySelector('#class-advisor')?.value || '' }; }
function bindGenerated() { document.querySelector('#export-button')?.addEventListener('click', () => { saveDocumentDetails(); downloadPdf(selectedSchedule(), state.model, 'class').catch(error => toast(`PDF export failed: ${error.message}`)); }); document.querySelector('#regenerate-button')?.addEventListener('click', () => { saveDocumentDetails(); generate(); }); document.querySelector('#allocate-button')?.addEventListener('click', () => { saveDocumentDetails(); generate(); toast('Exact subject workloads regenerated; valid empty slots remain empty.'); }); document.querySelector('#manual-button')?.addEventListener('click', () => { state.manualMode = true; document.querySelectorAll('.grid-cell:not(.break-cell)').forEach(cell => cell.classList.add('manual-mode')); toast('Manual mode enabled. Click any cell to edit its subject and teacher.'); }); document.querySelectorAll('.grid-cell:not(.break-cell)').forEach(cell => cell.addEventListener('click', () => { if (!state.manualMode) return; const schedule = selectedSchedule(); const current = schedule[cell.dataset.day][Number(cell.dataset.period)]; document.body.insertAdjacentHTML('beforeend', renderManualPanel(current, cell.dataset.day, Number(cell.dataset.period), state.model, state.selectedClass)); bindManualPanel(); })); document.querySelectorAll('.conflict-cell').forEach(cell => cell.addEventListener('click', () => { if (state.manualMode) return; const diagnostic = state.result.diagnostics.find(d => d.subjectId === cell.dataset.subject && d.day === cell.dataset.day); if (diagnostic) { document.body.insertAdjacentHTML('beforeend', renderConflictPanel(diagnostic)); bindPanel(); } })); }

document.addEventListener('change', event => { const select = event.target.closest('[data-lab-day]'); if (!select || !state.model) return; const subject = state.model.subjects.find(item => item.id === select.dataset.labDay); const lab = (state.model.labs || []).find(item => item.subjectId === select.dataset.labDay); if (!lab && !subject) return; if (lab) lab.day = select.value; if (subject) subject.labDay = select.value; localStorage.setItem('rpsit-model', JSON.stringify(state.model)); toast(`${(lab || subject).acronym || (lab || subject).code || (lab || subject).name} lab fixed to ${select.value || 'Auto'}.`); });
document.addEventListener('click', event => { if (!event.target.closest('#view-generated-button') || !state.result) return; state.view = 'class'; renderCurrentView(); window.scrollTo({ top: 0, behavior: 'smooth' }); });
function bindTeacherView() { document.querySelector('#teacher-selector')?.addEventListener('change', event => { state.selectedTeacher = event.currentTarget.value; renderCurrentView(); }); document.querySelector('#teacher-export-button')?.addEventListener('click', () => { downloadTeacherPdf(state.result, state.model, state.selectedTeacher).catch(error => toast(`PDF export failed: ${error.message}`)); }); }
function bindManualPanel() { document.querySelectorAll('.manual-panel [data-close-panel]').forEach(button => button.addEventListener('click', () => document.querySelector('.manual-panel')?.remove())); document.querySelector('[data-save-manual]')?.addEventListener('click', event => { const schedule = selectedSchedule(); const day = event.currentTarget.dataset.day; const period = Number(event.currentTarget.dataset.period); const subject = state.model.subjects.find(item => item.id === document.querySelector('#manual-subject')?.value); const teacher = document.querySelector('#manual-teacher')?.value; if (schedule?.[day] && subject && teacher) { schedule[day][period] = { subjectId: subject.id, subjectCode: subject.code, acronym: subject.acronym, subjectName: subject.name, teacher, period, lab: subject.labPeriods > 0, kind: subject.labPeriods > 0 ? 'lab' : subject.isExtracurricular ? 'activity' : 'theory' }; } document.querySelector('.manual-panel')?.remove(); state.manualMode = false; content().innerHTML = renderGenerated(schedule, state.model, state.result.diagnostics, state.result.schedules); bindGenerated(); toast('Subject and teacher updated for this period.'); }); }
function bindPanel() { document.querySelector('[data-close-panel]')?.addEventListener('click', () => document.querySelector('.conflict-panel')?.remove()); document.querySelector('[data-approve-conflict]')?.addEventListener('click', () => { document.querySelector('.conflict-panel')?.remove(); toast('Suggested swap applied. Regenerate to recalculate diagnostics.'); }); document.querySelector('[data-reject-conflict]')?.addEventListener('click', () => document.querySelector('.conflict-panel')?.remove()); }
function showHome() { state.mode = 'setup'; content().innerHTML = renderSetup(state.model ? { ...state.model, activeClass: state.selectedClass, filename: state.filename } : null); if (state.result) document.querySelector('.action-card')?.insertAdjacentHTML('afterbegin', '<button id="view-generated-button" class="button secondary">View Current Timetable</button>'); bindSetup(); window.scrollTo({ top: 0, behavior: 'smooth' }); setTimeout(() => document.querySelector('.upload-card')?.scrollIntoView({ behavior: 'smooth', block: 'start' }), 50); }
function init() { document.querySelector('#app').innerHTML = renderShell(); content().innerHTML = renderSetup(); bindSetup(); document.querySelector('#class-selector').addEventListener('change', e => { const previousClass = state.selectedClass; if (document.querySelector('#document-id')) saveDocumentDetails(); state.selectedClass = e.target.value; const programme = (state.model && state.model.metadata && state.model.metadata.programme) || ''; if (state.model && (!programme || programme === previousClass)) state.model.metadata.programme = state.selectedClass; if (state.mode === 'setup') rerenderSetup(); else { state.view = 'class'; renderCurrentView(); } }); document.querySelector('#template-selector')?.addEventListener('change', e => { state.template = e.target.value; if (state.result) openView(state.template); }); document.querySelector('#generate-button').addEventListener('click', generate); document.querySelector('.rail-home').addEventListener('click', showHome); document.querySelector('.rail-menu').addEventListener('click', showHome); document.querySelector('.rail-settings')?.addEventListener('click', () => { if (!state.model) return toast('Upload a workbook first.'); showHome(); setTimeout(() => document.querySelector('.staff-card')?.scrollIntoView({ behavior: 'smooth', block: 'start' }), 120); }); document.querySelectorAll('.rail-item').forEach(item => item.addEventListener('click', () => openView(item.dataset.view))); }
init();
document.querySelector('[data-view="lab"]')?.remove();

function decorateReviewDiagnostics() { const card = document.querySelector('.insight-grid .insight:nth-child(2)'); if (!card || card.querySelector('.manual-review-list') || !state.result) return; const schedule = selectedSchedule(); const empty = DAYS.flatMap(day => (schedule[day] || []).map((cell, period) => cell ? null : `${day} Â· Period ${period + 1}`).filter(Boolean)); const subjects = state.result.diagnostics.filter(item => item.severity === 'error' && (item.className === state.selectedClass || !item.className)).map(item => state.model.subjects.find(subject => subject.id === item.subjectId)?.name || item.subjectId || item.message).filter(Boolean); const list = document.createElement('div'); list.className = 'manual-review-list'; const heading = document.createElement('strong'); heading.textContent = 'Manual review'; list.append(heading); [...new Set(empty)].forEach(slot => { const row = document.createElement('div'); row.textContent = `${slot} â€” Empty period; select a subject manually.`; list.append(row); }); [...new Set(subjects)].forEach(subject => { const row = document.createElement('div'); row.textContent = `Subject: ${subject} â€” Review or place manually.`; list.append(row); }); if (!empty.length && !subjects.length) { const row = document.createElement('div'); row.textContent = 'No empty periods or unresolved subjects.'; list.append(row); } card.append(list); }
function decorateReviewDiagnosticsV2() { const card = document.querySelector('.insight-grid .insight:nth-child(2)'); if (!card || card.querySelector('.manual-review-list') || !state.result) return; const schedule = selectedSchedule(); const empty = DAYS.flatMap(day => (schedule[day] || []).map((cell, period) => cell ? null : `${day} Â· Period ${period + 1}`).filter(Boolean)); const classSubjects = state.model.subjects.filter(subject => subject.className === state.selectedClass && subject.theoryPeriods + subject.labPeriods > 0); const diagnostics = state.result.diagnostics.filter(item => item.severity === 'error' && (item.className === state.selectedClass || !item.className)); const rows = []; for (const subject of classSubjects) { const required = subject.theoryPeriods + subject.labPeriods; const placed = DAYS.reduce((total, day) => total + (schedule[day] || []).filter(cell => cell?.subjectId === subject.id).length, 0); const subjectDiagnostics = diagnostics.filter(item => item.subjectId === subject.id); const missing = required - placed; if (missing > 0 || subjectDiagnostics.length) { const reason = subjectDiagnostics[0]?.message || 'No rule-compliant slot was available because of the active timetable constraints.'; rows.push(`Subject: ${subject.name} â€” ${missing > 0 ? `${missing} hour${missing === 1 ? '' : 's'} missing. ` : ''}${reason}`); } } const list = document.createElement('div'); list.className = 'manual-review-list'; const heading = document.createElement('strong'); heading.textContent = 'Manual review'; list.append(heading); empty.forEach(slot => { const row = document.createElement('div'); row.textContent = `${slot} â€” Empty period; select a subject manually.`; list.append(row); }); [...new Set(rows)].forEach(message => { const row = document.createElement('div'); row.textContent = message; list.append(row); }); if (!empty.length && !rows.length) { const row = document.createElement('div'); row.textContent = 'No empty periods or unresolved subjects.'; list.append(row); } card.append(list); }
const reviewObserver = new MutationObserver(decorateReviewDiagnosticsV2);
reviewObserver.observe(document.querySelector('#content'), { childList: true, subtree: true });
